// Payload de los Database Webhooks de Supabase: { type, table, schema, record, old_record }.
// Cualquier otra cosa se ignora sin error.
const { type, table, record } = $input.first().json.body ?? {};
if (type !== 'INSERT' || table !== 'solicitudes' || !record?.id || !record?.estudiante_id) {
  return [];
}
return [{ json: record }];

const solicitud = $('Leer solicitud').first().json;
const estudiante = $('Buscar estudiante').first().json;
const admins = $('Buscar admins').all().map((item) => item.json).filter((admin) => admin.correo);
const app = $env.APP_URL.replace(/\/$/, '');

// Espejo de ETIQUETA_TIPO (web/src/lib/dominio.ts).
const TIPOS = {
  homologacion: 'Homologación',
  cancelacion_extemporanea: 'Cancelación extemporánea',
  supletorio: 'Supletorio',
  reingreso: 'Reingreso',
  comite_curricular: 'Solicitud al comité curricular',
  otro: 'Otro',
};
const ORIGENES = { web: 'la web', correo: 'correo electrónico' };

// El asunto y la descripción los escribe el estudiante: nunca van al HTML sin escapar.
const esc = (texto) => String(texto ?? '').replace(/[&<>"']/g, (c) =>
  ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]);

const tipo = TIPOS[solicitud.tipo] ?? solicitud.tipo;
const fecha = new Date(solicitud.creada).toLocaleString('es-CO', {
  timeZone: 'America/Bogota', dateStyle: 'long', timeStyle: 'short',
});
const resumen = `
<ul>
  <li><strong>Tipo:</strong> ${esc(tipo)}</li>
  <li><strong>Asunto:</strong> ${esc(solicitud.asunto)}</li>
  <li><strong>Recibida:</strong> ${esc(fecha)} por ${ORIGENES[solicitud.origen] ?? esc(solicitud.origen)}</li>
</ul>`;

const avisos = [{
  solicitud_id: solicitud.id,
  tipo_aviso: 'registro_estudiante',
  destinatario: estudiante.correo,
  asunto: `Recibimos tu solicitud: ${solicitud.asunto} - Gestión de Solicitudes`,
  cuerpo: `<h2>Recibimos tu solicitud</h2>
<p>Hola ${esc(estudiante.nombre)},</p>
<p>Tu solicitud quedó registrada como <strong>Pendiente</strong>. Te escribiremos cada vez que cambie de estado.</p>
${resumen}
<p><a href="${app}/mis-solicitudes/${solicitud.id}">Ver mi solicitud</a></p>`,
}];

const porRevisar = solicitud.revision === 'por_revisar'
  ? `<p><strong>Requiere revisión:</strong> ${esc(solicitud.motivo_revision ?? 'no se pudo clasificar automáticamente')}.</p>`
  : '';

for (const admin of admins) {
  avisos.push({
    solicitud_id: solicitud.id,
    tipo_aviso: 'registro_admin',
    destinatario: admin.correo,
    asunto: `Nueva solicitud: ${tipo} - Gestión de Solicitudes`,
    cuerpo: `<h2>Nueva solicitud</h2>
<p>${esc(estudiante.nombre)}${estudiante.id_estudiantil ? ` (ID ${esc(estudiante.id_estudiantil)})` : ''} registró una solicitud.</p>
${resumen}
${porRevisar}
<p><a href="${app}/gestion/solicitudes/${solicitud.id}">Gestionar la solicitud</a></p>`,
  });
}

return avisos.map((json) => ({ json }));
